// Technical indicators — a bit-exact port of indicators.py (pandas semantics).
//
// Every function takes plain number arrays and returns a Float64Array (NaN during
// warmup), so the JS backtest reproduces the Python engine trade for trade
// (pwa/tests/engine.test.mjs checks this against fixtures generated by Python).

const NAN = Number.NaN;

/** pandas Series.rolling(window).mean(): Kahan-compensated running sums, exactly as
 *  pandas' roll_mean (separate add/remove compensation, constant-run and sign rules). */
export function rollingMean(values, window) {
  const n = values.length;
  const out = new Float64Array(n).fill(NAN);
  let nobs = 0, sum = 0, neg = 0, compAdd = 0, compRemove = 0, same = 0, prev = NAN;
  const add = (v) => {
    if (v !== v) return;
    nobs += 1;
    const y = v - compAdd, t = sum + y;
    compAdd = t - sum - y; sum = t;
    if (v < 0 || Object.is(v, -0)) neg += 1;
    same = v === prev ? same + 1 : 1;
    prev = v;
  };
  const remove = (v) => {
    if (v !== v) return;
    nobs -= 1;
    const y = -v - compRemove, t = sum + y;
    compRemove = t - sum - y; sum = t;
    if (v < 0 || Object.is(v, -0)) neg -= 1;
  };
  for (let i = 0; i < n; i++) {
    const start = Math.max(0, i + 1 - window);
    if (i === 0) {
      prev = values[start];
      for (let j = start; j <= i; j++) add(values[j]);
    } else {
      for (let j = Math.max(0, i - window); j < start; j++) remove(values[j]);
      add(values[i]);
    }
    if (nobs >= window && nobs > 0) {
      let r = sum / nobs;
      if (same >= nobs) r = prev;
      else if (neg === 0 && r < 0) r = 0;
      else if (neg === nobs && r > 0) r = 0;
      out[i] = r;
    }
  }
  return out;
}

export const sma = rollingMean;

function rollingExtreme(values, window, pick) {
  const n = values.length;
  const out = new Float64Array(n).fill(NAN);
  for (let i = window - 1; i < n; i++) {
    let best = values[i - window + 1];
    let valid = best === best;
    for (let j = i - window + 2; valid && j <= i; j++) {
      const v = values[j];
      if (v !== v) valid = false;
      else best = pick(best, v);
    }
    if (valid) out[i] = best;
  }
  return out;
}

/** Highest value over the last `window` bars including today. */
export const rollingMax = (values, window) => rollingExtreme(values, window, Math.max);
/** Lowest value over the last `window` bars including today. */
export const rollingMin = (values, window) => rollingExtreme(values, window, Math.min);

export function shift(values, periods) {
  const out = new Float64Array(values.length).fill(NAN);
  for (let i = periods; i < values.length; i++) out[i] = values[i - periods];
  return out;
}

/** Highest value over the `lookback` bars BEFORE each bar (today excluded). */
export const priorMax = (values, lookback) => rollingMax(shift(values, 1), lookback);
/** Lowest value over the `lookback` bars BEFORE each bar. */
export const priorMin = (values, lookback) => rollingMin(shift(values, 1), lookback);

/** Rate of change over `period` bars (0.10 = +10%). */
export function roc(close, period) {
  const out = new Float64Array(close.length).fill(NAN);
  for (let i = period; i < close.length; i++) out[i] = close[i] / close[i - period] - 1;
  return out;
}

/** True Range; the first bar has no prior close, so it is high - low (pandas max skips NaN). */
export function trueRange(high, low, close) {
  const out = new Float64Array(close.length);
  for (let i = 0; i < close.length; i++) {
    const hl = high[i] - low[i];
    out[i] = i === 0 ? hl : Math.max(hl, Math.abs(high[i] - close[i - 1]), Math.abs(low[i] - close[i - 1]));
  }
  return out;
}

export const atr = (high, low, close, period) => rollingMean(trueRange(high, low, close), period);

/** True where `condition` held on each of the last `bars` bars including today. */
export function heldForBars(condition, bars) {
  const out = new Uint8Array(condition.length);
  let run = 0;
  for (let i = 0; i < condition.length; i++) {
    run = condition[i] ? run + 1 : 0;
    out[i] = run >= bars ? 1 : 0;
  }
  return out;
}

/** ROC(momLookback) / (ATR(atrPeriod) / close); NaN where ATR or price is not positive. */
export function volAdjustedMomentum(bars, momLookback, atrPeriod) {
  const momentum = roc(bars.close, momLookback);
  const range = atr(bars.high, bars.low, bars.close, atrPeriod);
  const out = new Float64Array(bars.close.length).fill(NAN);
  for (let i = 0; i < out.length; i++) {
    if (range[i] > 0 && bars.close[i] > 0) out[i] = momentum[i] / (range[i] / bars.close[i]);
  }
  return out;
}
